CREATE TABLE screening_cases(id RAW(16) DEFAULT SYS_GUID() PRIMARY KEY, payment_id RAW(16) NOT NULL REFERENCES payments(id), verdict VARCHAR2(20) DEFAULT 'REVIEW' NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE policies(code VARCHAR2(50) PRIMARY KEY, effect VARCHAR2(20) NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE policy_decisions(id RAW(16) DEFAULT SYS_GUID() PRIMARY KEY, screening_case_id RAW(16) NOT NULL REFERENCES screening_cases(id), policy_code VARCHAR2(50) NOT NULL REFERENCES policies(code), created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
